/**
 * @helios/oui — motion 层(可选,基于 anime.js v4)
 *
 * 设计原则(anthropic frontend-design):
 *   • motion 要 deliberate:编排的入场 > 散落的效果
 *   • less is more:不需要的地方不要动画
 *   • reduced-motion 必须尊重
 *
 * anime.js 是 optionalDependency:
 *   • 装了 → 用 anime.js 做高级编排(stagger/timeline/spring)
 *   • 没装 → 降级,函数变 no-op 或回退 CSS,不报错
 *
 * 用法:
 *   import { staggerReveal, animateValue } from '@helios/oui/motion';
 *   staggerReveal('.card', { delay: 60 });          // 列表交错入场
 *   animateValue(el, { from: 0, to: 48392 });        // 数字滚动
 */
interface StaggerRevealOptions {
    /** 每个元素间隔 ms,默认 60 */
    delay?: number;
    /** 单元素时长 ms,默认 500 */
    duration?: number;
    /** 从哪个方向交错:'first' | 'last' | 'center',默认 'first' */
    from?: 'first' | 'last' | 'center';
    /** Y 位移起点 px,默认 12 */
    translateY?: number;
}
/**
 * 列表交错入场 — 编排式,比散落的单个 fade 更"deliberate"
 * 降级:reduced-motion 或未装 anime.js 时,直接显示(无动画)
 */
declare function staggerReveal(target: string | HTMLElement | HTMLElement[], opts?: StaggerRevealOptions): Promise<void>;
interface AnimateValueOptions {
    from?: number;
    to: number;
    duration?: number;
    /** 格式化,如千分位 */
    format?: (v: number) => string;
}
/**
 * 数字滚动动画 — KPI/metric 用
 * 降级:未装 anime.js 时直接设最终值
 */
declare function animateValue(el: HTMLElement, opts: AnimateValueOptions): Promise<void>;
/**
 * 页面/区块入场编排 timeline
 * 降级:未装时 no-op
 */
declare function orchestrate(steps: Array<{
    target: string | HTMLElement;
    props: Record<string, unknown>;
    at?: string | number;
}>): Promise<void>;
/** 是否可用 anime.js(已安装且非 reduced-motion) */
declare function motionAvailable(): Promise<boolean>;

export { type AnimateValueOptions, type StaggerRevealOptions, animateValue, motionAvailable, orchestrate, staggerReveal };
